def findStrobogrammatic(n: int) -> list[str]:
    pairs = [('0', '0'), ('1', '1'), ('8', '8'), ('6', '9'), ('9', '6')]
    def helper(m):
        if m == 0: return [""]
        if m == 1: return ["0", "1", "8"]
        prev = helper(m - 2)
        curr = []
        for p in prev:
            for l, r in pairs:
                if m != n or l != '0':
                    curr.append(l + p + r)
        return curr
    return sorted(helper(n))

